import api from './api';

export const authService = {
  // Set auth token for API calls
  setAuthToken: (token) => {
    if (token) {
      api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
    }
  },

  // Remove auth token
  removeAuthToken: () => {
    delete api.defaults.headers.common['Authorization'];
  },

  // Login user
  login: async (credentials) => {
    try {
      const response = await api.post('/api/auth/login', credentials);
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Register user
  register: async (userData) => {
    try {
      const response = await api.post('/api/auth/register', userData);
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Verify user account
  verify: async (token) => {
    try {
      const response = await api.get(`/api/auth/verify?token=${token}`);
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Get user profile
  getProfile: async () => {
    try {
      const response = await api.get('/api/auth/profile');
      return response;
    } catch (error) {
      throw error;
    }
  },

  // Test auth endpoint
  testAuth: async () => {
    try {
      const response = await api.get('/api/auth/test');
      return response;
    } catch (error) {
      throw error;
    }
  }
};
